#include <sqlite3.h>
#include <stdio.h>
#include <string.h>
#include "surface_maturity.h"
#include "source_constellations.h"
#include "../../../lib/libbonfyre/include/bf_command_lookup.h"

static int scalar2(sqlite3*d,const char*q,int*out){sqlite3_stmt*s=NULL;int ok=0;if(sqlite3_prepare_v2(d,q,-1,&s,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(s,1,bf_source_constellations_json,-1,SQLITE_STATIC);sqlite3_bind_text(s,2,bf_surface_maturity_json,-1,SQLITE_STATIC);if(sqlite3_step(s)==SQLITE_ROW){*out=sqlite3_column_int(s,0);ok=1;}sqlite3_finalize(s);return ok;}

static int audit(sqlite3*d){
 int worlds=0,entry=0,path=0,proj=0,impact=0,outside=0,featured=0;
 if(!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds')",&worlds)||!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds') w WHERE NOT EXISTS(SELECT 1 FROM json_each(w.value,'$.surface_projection') p WHERE p.value=json_extract(w.value,'$.entry_surface'))",&entry)||!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds') w,json_each(w.value,'$.visitor_path') v WHERE NOT EXISTS(SELECT 1 FROM json_each(w.value,'$.surface_projection') p WHERE p.value=v.value)",&path)||!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds') w,json_each(w.value,'$.surface_projection') p WHERE NOT EXISTS(SELECT 1 FROM json_each(?2,'$.surfaces') m WHERE json_extract(m.value,'$.surface')=p.value)",&proj)||!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds') w,json_each(w.value,'$.sources') s,json_each(s.value,'$.surfaces') p WHERE NOT EXISTS(SELECT 1 FROM json_each(?2,'$.surfaces') m WHERE json_extract(m.value,'$.surface')=p.value)",&impact)||!scalar2(d,"SELECT count(*) FROM json_each(?1,'$.worlds') w,json_each(w.value,'$.sources') s,json_each(s.value,'$.surfaces') sp WHERE NOT EXISTS(SELECT 1 FROM json_each(w.value,'$.surface_projection') p WHERE p.value=sp.value)",&outside)||!scalar2(d,"SELECT json_array_length(json_extract(value,'$.surface_projection')) FROM json_each(?1,'$.worlds') WHERE json_extract(value,'$.featured')=1",&featured))return 0;
 printf("{\"schema\":\"bonfyre-public-world-audit.v1\",\"worlds\":%d,\"entry_missing\":%d,\"visitor_path_missing\":%d,\"unknown_projection_surfaces\":%d,\"unknown_source_impact_surfaces\":%d,\"source_impacts_outside_world\":%d,\"featured_projection_count\":%d,\"truth\":\"cross_contract_projection_integrity_only\"}\n",worlds,entry,path,proj,impact,outside,featured);
 return worlds==5&&entry==0&&path==0&&proj==0&&impact==0&&outside==0&&featured==22;
}

static int project(sqlite3*d,const char*world){
 sqlite3_stmt*s=NULL;
 const char*q="WITH chosen(world) AS (SELECT value FROM json_each(?1,'$.worlds') WHERE json_extract(value,'$.id')=?3), sources_by_surface(surface,candidates) AS (SELECT sp.value,json_group_array(json_object('source',json_extract(x.value,'$.id'),'label',json_extract(x.value,'$.label'),'authority',json_extract(x.value,'$.authority'),'url',json_extract(x.value,'$.url'),'carrier',json_extract(x.value,'$.carrier'),'auth',json_extract(x.value,'$.auth'),'protocols',json(json_extract(x.value,'$.protocols')),'truth',json_extract(x.value,'$.truth'))) FROM chosen w,json_each(w.world,'$.sources') x,json_each(x.value,'$.surfaces') sp GROUP BY sp.value), projections(ord,projection) AS (SELECT p.key,json_object('surface',p.value,'route',json_extract(m.value,'$.route'),'question',json_extract(m.value,'$.question'),'owners',json(json_extract(m.value,'$.owners')),'runtime_owners',json(json_extract(m.value,'$.runtime_owners')),'same_world_transitions',json(json_extract(m.value,'$.transitions')),'anonymous_use',json_extract(m.value,'$.anonymous_use'),'effect_aperture',json_extract(m.value,'$.effect_aperture'),'truth_boundary',json_extract(m.value,'$.truth_boundary'),'source_candidates',json(COALESCE(sb.candidates,'[]')),'truth','owner_projection_plus_unobserved_source_candidates') FROM chosen w,json_each(w.world,'$.surface_projection') p JOIN json_each(?2,'$.surfaces') m ON json_extract(m.value,'$.surface')=p.value LEFT JOIN sources_by_surface sb ON sb.surface=p.value) SELECT json_object('schema','bonfyre-public-world.v1','world',json_extract(w.world,'$.id'),'label',json_extract(w.world,'$.label'),'entry_surface',json_extract(w.world,'$.entry_surface'),'question',json_extract(w.world,'$.question'),'visitor_path',json(json_extract(w.world,'$.visitor_path')),'projections',json((SELECT json_group_array(json(projection)) FROM (SELECT projection FROM projections ORDER BY ord))),'truth','world_projection_plan_not_owner_state') FROM chosen w";
 if(sqlite3_prepare_v2(d,q,-1,&s,NULL)!=SQLITE_OK){fprintf(stderr,"project sql: %s\n",sqlite3_errmsg(d));return 0;}
 sqlite3_bind_text(s,1,bf_source_constellations_json,-1,SQLITE_STATIC);sqlite3_bind_text(s,2,bf_surface_maturity_json,-1,SQLITE_STATIC);sqlite3_bind_text(s,3,world,-1,SQLITE_TRANSIENT);
 if(sqlite3_step(s)!=SQLITE_ROW||!sqlite3_column_text(s,0)){sqlite3_finalize(s);return 0;}puts((const char*)sqlite3_column_text(s,0));sqlite3_finalize(s);return 1;
}

int main(int argc,char**argv){sqlite3*d=NULL;int ok=0;if(argc<2||sqlite3_open(":memory:",&d)!=SQLITE_OK)return 2;enum{PW_AUDIT,PW_PROJECT};static const BfCommandEntry world_commands[]={{"audit",PW_AUDIT,0,NULL},{"project",PW_PROJECT,0,NULL},};const BfCommandEntry*command=bf_command_lookup(world_commands,sizeof(world_commands)/sizeof(world_commands[0]),argv[1]);if(command&&command->id==PW_AUDIT)ok=audit(d);else if(command&&command->id==PW_PROJECT&&argc==3)ok=project(d,argv[2]);else fprintf(stderr,"usage: bonfyre-public-world audit | project WORLD\n");sqlite3_close(d);return ok?0:1;}
